from pathlib import Path

p=Path('admin-stocktake.html')
s=p.read_text()


def replace_between(text,start,end,replacement):
    a=text.find(start)
    if a<0: raise SystemExit(f'missing start: {start}')
    b=text.find(end,a)
    if b<0: raise SystemExit(f'missing end: {end}')
    return text[:a]+replacement+text[b:]

# Management-approved model: current inventory is the source; Excel is export/legacy only.
