campaign_funcs='''function campaignsHtml(cp){return `<div class="row"><div class="grow"><h2>ملفات الجرد</h2><div class="muted">الجرد الجديد يأخذ لقطة مباشرة من المخزون الحالي. جهّز الفريق ثم ابدأ صباحًا أو ليلًا بعد اكتمال تحديث المخزون.</div></div><button id="testCampaign" class="btn info">🧪 تجربة</button><button id="newCampaign" class="btn primary">+ جرد جديد</button></div><div class="campaigns section">${state.campaigns.length?state.campaigns.slice(0,10).map(c=>`<button data-campaign="${c.id}" class="card ${cp?.id===c.id?'active':''}" style="text-align:right"><div class="cardtop"><div class="grow"><b style="font-size:12px">${esc(c.name||`جرد ${c.warehouse||''}`)}</b><div class="muted">${esc(c.warehouse||'—')} · ${esc(c.stocktakeDate||'بدون تاريخ')}</div></div>${c.isTest?'<span class="pill info">اختبار</span>':c.sourceMode==='current_inventory'?'<span class="pill ok">المخزون الحالي</span>':''}<span class="pill ${c.status==='active'?'ok':c.status==='closed'?'bad':c.status==='ready'?'info':''}">${campaignStatus(c.status)}</span></div></button>`).join(''):'<div class="empty">لا توجد ملفات جرد بعد.</div>'}</div>`}
function campaignSummary(cp,total,counted,pending,matched,short,surplus,notes){const direct=cp.sourceMode==='current_inventory',ready=cp.status==='ready',active=cp.status==='active',closed=cp.status==='closed';return `<div class="row"><div class="grow"><h2>${esc(cp.name||`جرد ${cp.warehouse||''}`)}</h2><div class="muted">${esc(cp.warehouse||'—')} · ${esc(cp.stocktakeDate||'—')} · ${campaignStatus(cp.status)}</div></div><span class="pill ${active?'ok':closed?'bad':ready?'info':''}">${campaignStatus(cp.status)}</span></div><div class="stats section">${stat('الأصناف',total)}${stat('تم الجرد',counted)}${stat('متبقي',pending)}${stat('مطابق',matched)}${stat('نواقص',short)}${stat('زيادات',surplus)}</div><div class="summaryActions section"><button id="markReady" class="btn ${cp.status==='draft'?'primary primaryAction':'info'}" ${cp.status!=='draft'?'disabled':''}>اعتماد التجهيز</button><button id="activateCampaign" class="btn ${ready?'ok primaryAction':'ok'}" ${active||closed?'disabled':''}>بدء الجرد الآن</button>${active?`<button id="closeCampaign" class="btn bad primaryAction">${cp.isTest?'إنهاء التجربة':'إنهاء الجرد وإرساله للتسوية'}</button>`:`<button id="closeCampaign" class="btn bad" disabled>${cp.isTest?'إنهاء التجربة':'إنهاء الجرد'}</button>`}${closed?'<button id="reopenCampaign" class="btn primaryAction">إعادة فتح الجرد</button>':''}</div><details class="moreActions"><summary>التقارير والمزيد</summary><div class="row"><button id="printReport" class="btn">طباعة محضر الجرد</button><button id="exportDiff" class="btn bad">Excel الفروقات</button><button id="exportAll" class="btn info">Excel كامل</button></div></details>${direct?`<div class="success">✓ المصدر: المخزون الحالي مباشرة. تم حفظ لقطة مرجعية من ${esc(cp.warehouse||'المستودع')} ولا تحتاج رفع Excel.</div>`:''}${cp.isTest?'<div class="success">🧪 وضع اختبار معزول — لا يغيّر المخزون الحقيقي.</div>':''}<div class="muted section">لا يوجد أي تعديل تلقائي للمخزون. نتائج الجرد مرجع للتسوية فقط، والتعديل الفعلي يبقى في النظام المحاسبي.</div>`}
'''
s=replace_between(s,'function campaignsHtml(cp){','function stat(l,v){',campaign_funcs)

team_funcs='''function teamsHtml(cp){const canEdit=cp.status!=='closed',direct=cp.sourceMode==='current_inventory'&&!cp.isTest;return `<div class="section"><div class="row"><div class="grow"><h3>${direct?'فريق الجرد':'لجان / مجموعات الجرد'}</h3><div class="muted">${direct?'الجرد موحد على لقطة المخزون الحالية لمنع تكرار الصنف بين أكثر من لجنة. عدّل أعضاء الفريق حسب الحاجة.':'كل مجموعة لها نطاق مستقل. عدد الأعضاء غير محدود.'}</div></div>${direct?'':`<button id="newTeam" class="btn" ${canEdit?'':'disabled'}>+ مجموعة</button>`}</div><div class="teams section">${state.teams.length?state.teams.map(t=>{const its=state.items.filter(i=>i.teamId===t.id),done=its.filter(i=>(i.countStatus||'pending')!=='pending').length,p=its.length?Math.round(done/its.length*100):0,v=its.filter(i=>['shortage','surplus'].includes(i.countStatus)).length;return `<div class="card"><div class="cardtop"><div class="grow"><b style="font-size:12px">${esc(t.name)}</b><div class="muted">${esc(t.scope||t.zone||'بدون نطاق')}</div><div class="roster">عضو اللجنة / المساعد: ${teamRoster(t).length?esc(teamRoster(t).join('، ')):'لم يحدد أعضاء بعد'}</div></div><span class="pill ${p===100&&its.length?'ok':''}">${done}/${its.length}</span></div><div class="progress"><i style="width:${p}%"></i></div><div class="row" style="margin-top:8px"><span class="pill">${p}%</span>${v?`<span class="pill bad">${v} فروقات</span>`:''}<button data-edit-team="${t.id}" class="btn" ${canEdit?'':'disabled'}>تعديل الأعضاء والنطاق</button>${!direct&&['draft','ready'].includes(cp.status)?`<button data-delete-team="${t.id}" class="btn bad">حذف</button>`:''}</div></div>`}).join(''):'<div class="empty">لم تتم إضافة فريق الجرد بعد.</div>'}</div></div>`}
function importHtml(cp){if(cp.isTest)return '<div class="success section">🧪 أصناف هذه التجربة مأخوذة تلقائيًا من المخزون الحالي؛ رفع Excel غير مطلوب في وضع الاختبار.</div>';if(cp.sourceMode==='current_inventory')return '<div class="success section">✓ تم تثبيت أصناف وكميات المخزون عند إنشاء الجرد. لا يوجد رفع Excel لهذا الجرد؛ Excel متاح فقط كتقرير بعد العد.</div>';const im=state.import,canImport=['draft','ready'].includes(cp.status);return `<div class="section"><h3>رفع ملف Excel لكل مجموعة — حملات قديمة فقط</h3><div class="muted">هذا المسار محفوظ للحملات السابقة فقط.</div><div class="importbox section"><div class="fields"><div class="field"><label>المجموعة</label><select id="importTeam" class="select" ${canImport?'':'disabled'}><option value="">اختر المجموعة</option>${state.teams.map(t=>`<option value="${t.id}" ${im.teamId===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div class="field"><label>ملف Excel / CSV</label><input id="importFile" type="file" accept=".xlsx,.xls,.csv" class="input" ${canImport?'':'disabled'}></div></div>${im.headers.length?mappingHtml(im):''}</div></div>`}
'''
s=replace_between(s,'function teamsHtml(cp){','function mappingHtml(im){',team_funcs)

review_funcs='''function mobileItemCard(i){const counted=(i.countStatus||'pending')!=='pending',diff=counted?Number(i.difference):null;return `<article class="mobileItem"><div class="mobileItemHead"><div class="grow"><div class="mobileSku">${esc(i.sku)}</div><div class="mobileName">${esc(i.name||'')}${i.pack!==''&&i.pack!=null?` · الشد ${esc(i.pack)}`:''}</div></div><span class="pill ${i.countStatus==='matched'?'ok':i.countStatus==='shortage'?'bad':i.countStatus==='surplus'?'info':''}">${itemStatus(i.countStatus)}</span></div><div class="mobileMeta"><div class="mobileMetric"><span>كمية النظام</span><b>${fmt(i.expectedQty)}</b></div><div class="mobileMetric"><span>الفعلي</span><b>${counted?fmt(i.actualQty):'—'}</b></div><div class="mobileMetric"><span>الفرق</span><b>${counted?`${diff>0?'+':''}${fmt(diff)}`:'—'}</b></div></div><div class="mobileFoot"><b>${esc(teamName(i.teamId))}</b>${teamScope(i.teamId)?` · ${esc(teamScope(i.teamId))}`:''}${i.note?`<br>ملاحظة: ${esc(i.note)}`:''}${i.updatedByName?`<br>آخر تسجيل: ${esc(i.updatedByName)}`:''}</div></article>`}
function reviewHtml(cp){let rows=state.items,q=norm(state.search);if(state.tab==='pending')rows=rows.filter(i=>(i.countStatus||'pending')==='pending');if(state.tab==='shortage')rows=rows.filter(i=>i.countStatus==='shortage');if(state.tab==='surplus')rows=rows.filter(i=>i.countStatus==='surplus');if(state.tab==='variance')rows=rows.filter(i=>['shortage','surplus'].includes(i.countStatus));if(state.tab==='notes')rows=rows.filter(i=>String(i.note||'').trim());if(state.tab==='matched')rows=rows.filter(i=>i.countStatus==='matched');if(q)rows=rows.filter(i=>norm(`${i.sku} ${i.name||''} ${i.note||''} ${teamName(i.teamId)}`).includes(q));rows=rows.sort((a,b)=>teamName(a.teamId).localeCompare(teamName(b.teamId),'ar')||(a.orderIndex??999999)-(b.orderIndex??999999)).slice(0,700);const desktopRows=`<div class="tablewrap"><table class="table"><thead><tr><th>المجموعة</th><th>نطاق الجرد</th><th>الصنف</th><th>الشد</th><th>كمية النظام</th><th>الفعلي</th><th>الفرق</th><th>الحالة</th><th>الملاحظة</th><th>آخر تسجيل</th><th>التعديلات</th></tr></thead><tbody>${rows.length?rows.map(i=>`<tr><td>${esc(teamName(i.teamId))}</td><td>${esc(teamScope(i.teamId))}</td><td><b>${esc(i.sku)}</b><div class="muted">${esc(i.name||'')}</div></td><td>${esc(i.pack??'—')}</td><td>${fmt(i.expectedQty)}</td><td>${(i.countStatus||'pending')!=='pending'?fmt(i.actualQty):'—'}</td><td>${(i.countStatus||'pending')!=='pending'?`${Number(i.difference)>0?'+':''}${fmt(i.difference)}`:'—'}</td><td><span class="pill ${i.countStatus==='matched'?'ok':i.countStatus==='shortage'?'bad':i.countStatus==='surplus'?'info':''}">${itemStatus(i.countStatus)}</span></td><td class="note">${esc(i.note||'')}</td><td>${esc(i.updatedByName||'—')}</td><td>${fmt(i.revision||0)}</td></tr>`).join(''):'<tr><td colspan="11" class="empty">لا توجد نتائج.</td></tr>'}</tbody></table></div>`;return `<div class="section"><div class="row reviewHead"><div class="grow"><h3>متابعة الجرد والتسوية</h3><div class="muted">متابعة مباشرة للفروقات والعد. على الجوال تظهر الأصناف كبطاقات واضحة بدل الجدول العريض.</div></div><input id="reviewSearch" class="input reviewSearch" value="${esc(state.search)}" placeholder="رقم الصنف / الاسم / المجموعة"></div><div class="tabs">${tab('all','الكل')}${tab('pending','متبقي')}${tab('matched','مطابق')}${tab('variance','الفروقات')}${tab('shortage','النواقص')}${tab('surplus','الزيادات')}${tab('notes','ملاحظات')}${tab('audit','سجل التعديلات')}</div>${state.tab==='audit'?`<div class="desktopOnly">${auditHtml()}</div><div class="mobileOnly">${auditCardsHtml()}</div>`:`<div class="desktopOnly">${desktopRows}</div><div class="mobileOnly mobileItems">${rows.length?rows.map(mobileItemCard).join(''):'<div class="empty">لا توجد نتائج.</div>'}</div>`}</div>`}
'''
s=replace_between(s,'function reviewHtml(cp){','function tab(id,label){',review_funcs)

audit_cards='''function auditCardsHtml(){const labels={count_created:'اعتماد العد الأول',count_revised:'تعديل الجرد',quantity_found_later:'كمية عُثر عليها',note_updated:'تعديل ملاحظة',team_created:'إنشاء مجموعة',team_updated:'تعديل المجموعة',team_deleted:'حذف مجموعة',team_items_imported:'اعتماد ملف قديم',campaign_created:'إنشاء الجرد',test_campaign_created:'إنشاء تجربة',campaign_ready:'اعتماد التجهيز',campaign_activated:'بدء الجرد',campaign_closed:'إغلاق الجرد',campaign_reopened:'إعادة فتح الجرد'};const a=state.audit.slice(0,250);return `<div class="mobileAudit">${a.length?a.map(x=>`<article class="mobileItem"><div class="mobileItemHead"><div class="grow"><b>${esc(labels[x.action]||x.action||'حركة')}</b><div class="mobileName">${dt(x.createdAt)} · ${esc(x.actorName||'—')}</div></div>${x.sku?`<span class="pill">${esc(x.sku)}</span>`:''}</div></article>`).join(''):'<div class="empty">لا توجد تعديلات بعد.</div>'}</div>`}
'''
s=s.replace('\nfunction printHtml(cp){','\n'+audit_cards+'function printHtml(cp){',1)

create_block='''function openCampaignModal(){const d=new Date(Date.now()+3*3600*1000).toISOString().slice(0,10);$('#campaignDate').value=d;$('#campaignWarehouse').value='jeddah';$('#campaignName').value='';$('#campaignModal').classList.add('open');setTimeout(()=>$('#campaignWarehouse').focus(),60)}
$('#campaignCancel').onclick=()=>$('#campaignModal').classList.remove('open');$('#campaignModal').onclick=e=>{if(e.target.id==='campaignModal')$('#campaignCancel').click()};$('#campaignCreate').onclick=()=>createCurrentInventoryCampaign();
async function createCurrentInventoryCampaign(){const key=$('#campaignWarehouse').value,source=TEST_INVENTORY_SOURCES[key]||TEST_INVENTORY_SOURCES.jeddah,stocktakeDate=$('#campaignDate').value,name=$('#campaignName').value.trim()||`جرد ${source.label} — ${stocktakeDate}`,button=$('#campaignCreate');if(!stocktakeDate)return toast('حدد تاريخ الجرد');button.disabled=true;button.textContent='جاري تثبيت المخزون...';let campaignRef=null;try{const active=activeStocktakeCampaign();if(active)throw new Error('ACTIVE_STOCKTAKE_EXISTS');const response=await fetch(`${source.url}?stocktake=${Date.now()}`,{cache:'no-store'});if(!response.ok)throw new Error(`INVENTORY_HTTP_${response.status}`);const raw=parseTestInventoryTsv(await response.text()),dedup=new Map();raw.forEach(r=>dedup.set(norm(r.sku),r));const rows=[...dedup.values()];if(!rows.length)throw new Error('NO_INVENTORY_ROWS');campaignRef=db.collection('stocktake_campaigns').doc();const teamRef=db.collection('stocktake_teams').doc(),now=firebase.firestore.FieldValue.serverTimestamp(),scope=`المخزون الكامل — ${source.label}`,campaignPayload={name,warehouse:source.label,warehouseKey:key,stocktakeDate,status:'draft',sourceMode:'current_inventory',inventorySnapshotStatus:'loading',inventorySnapshotCount:0,schemaVersion:3,createdAt:now,createdBy:'مهند'},teamPayload={campaignId:campaignRef.id,name:'فريق الجرد',scope,zone:scope,memberEmployeeIds:[ROOT_ID],memberEmployeeNames:['مهند'],extraMemberNames:[],status:'active',sourceMode:'current_inventory',orderIndex:0,updatedAt:now,updatedBy:'مهند',createdAt:now,createdBy:'مهند',schemaVersion:3};const first=db.batch();first.set(campaignRef,campaignPayload);first.set(teamRef,teamPayload);await first.commit();for(let x=0;x<rows.length;x+=350){const b=db.batch();rows.slice(x,x+350).forEach((r,j)=>b.set(db.collection('stocktake_items').doc(itemId(campaignRef.id,r.sku)),{campaignId:campaignRef.id,campaignName:name,teamId:teamRef.id,teamName:teamPayload.name,scope,zone:scope,sku:r.sku,normalizedSku:norm(r.sku),name:r.name,expectedQty:Number(r.qty),pack:r.pack,countStatus:'pending',actualQty:null,difference:null,note:'',hasNote:false,revision:0,orderIndex:x+j,updatedAt:now,importedAt:now,importedBy:'مهند',importFileName:'',sourceMode:'current_inventory',inventorySnapshot:true,schemaVersion:3}));await b.commit()}await campaignRef.set({inventorySnapshotStatus:'ready',inventorySnapshotCount:rows.length,inventorySnapshotCapturedAt:firebase.firestore.FieldValue.serverTimestamp()},{merge:true});state.campaign={id:campaignRef.id,...campaignPayload,inventorySnapshotStatus:'ready',inventorySnapshotCount:rows.length,createdAt:null};state.import={file:null,rows:[],headers:[],map:{sku:'',qty:'',pack:'',name:''},teamId:'',errors:[],headerRow:0};$('#campaignCancel').click();bindSelected();render();await auditAdmin('campaign_created',{campaignId:campaignRef.id,name,warehouse:source.label,stocktakeDate,sourceMode:'current_inventory',itemCount:rows.length});toast(`تم إنشاء الجرد من مخزون ${source.label}: ${rows.length} صنف`)}catch(e){console.error(e);if(campaignRef)campaignRef.set({inventorySnapshotStatus:'error',inventorySnapshotError:String(e?.message||e),updatedAt:firebase.firestore.FieldValue.serverTimestamp()},{merge:true}).catch(()=>{});toast(e.message==='ACTIVE_STOCKTAKE_EXISTS'?'أنه الجرد النشط أولًا قبل إنشاء جرد جديد':e.message==='NO_INVENTORY_ROWS'?'لم يتم العثور على أصناف في المخزون الحالي':'تعذر إنشاء لقطة الجرد من المخزون الحالي')}finally{button.disabled=false;button.textContent='إنشاء من المخزون الحالي'}}
'''
s=replace_between(s,'function openCampaignModal(){','function openTeam(id){',create_block)

readiness='''function campaignReadiness(){const problems=[];if(state.campaign?.sourceMode==='current_inventory'&&state.campaign?.inventorySnapshotStatus!=='ready')problems.push('لقطة المخزون لم تكتمل بعد');if(!state.teams.length)problems.push('لا يوجد فريق جرد');for(const t of state.teams){const count=state.items.filter(i=>i.teamId===t.id).length;if(!count)problems.push(`${t.name}: لا توجد أصناف`);if(!teamIds(t).length)problems.push(`${t.name}: لا يوجد عضو صاحب حساب يستطيع التسجيل`)}return problems}
'''
